9	using Microsoft.AspNetCore.Mvc;
10	using System.Text.Json;
11	
12	namespace chatai_backend.Controllers
13	{
14	    /// <summary>
15	    /// flowId=7（學習規劃探索助手）的探索紀錄 CRUD。實際跟 AI 對話走 /api/run
16	    /// （RunController.RunAdvisingExploreFlow），這裡只負責建立/查詢/更新/刪除紀錄本身。
17	    /// 一律用 JWT 的 accountName 當作資料歸屬與存取控制依據，不接受前端指定使用者身份，
18	    /// 也不會把 accountName 傳給 AI（AdvisingChatService 只吃 question + history）。
19	    /// </summary>
20	    [Route("api/explorations")]
21	    public class ExplorationController : BaseApiController
22	    {
23	        private readonly IChataiModule _chataiModule;
24	        private readonly IAdvisingChatService _advisingService;
25	
26	        public ExplorationController(IChataiModule chataiModule, IAdvisingChatService advisingService)
27	        {
28	            _chataiModule = chataiModule;
29	            _advisingService = advisingService;
30	        }
31	
32	        [HttpPost]
33	        public IActionResult Create([FromBody] CreateExplorationRequest request)
34	        {
35	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
36	            if (string.IsNullOrEmpty(userId))
37	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
38	
39	            if (string.IsNullOrWhiteSpace(request.Topic))
40	                return BadRequest("Missing topic.");
41	
42	            var now = DateTime.Now;
43	
44	            // 預先把「開場白這輪」寫進 history，讓 Critical Conversation State Rule 判定 Stage 1
45	            // 已經跑過，議題一送出（RunController.RunAdvisingExploreFlow）就直接進 Stage 1.5 自評，
46	            // 不會重複輸出開場白。這段開場白同時也是前端 TopicSelectPage 顯示的靜態文案
47	            // （見 _frontend/chatai/apps/explore/src/i18n/zh-TW.json 的 topics.opening）。
48	            var openingHistory = new List<(string Role, string Text)>
49	            {
50	                ("user", "start"),
51	                ("model", _advisingService.GetOpeningText())
52	            };
53	
54	            var record = new Exploration
55	            {
56	                id = Guid.NewGuid(),
57	                account_name = userId,
58	                topic = request.Topic,
59	                topic_custom_label = request.TopicCustomLabel,
60	                status = "in-progress",
61	                history_json = ExplorationHistoryJson.Serialize(openingHistory),
62	                is_del = false,
63	                create_date = now,
64	                update_date = now,
65	            };
66	
67	            if (!_chataiModule.AddExploration(record))
68	                return BadRequest("建立探索紀錄失敗。");
69	
70	            return Ok(ToResponse(record));
71	        }
72	
73	        [HttpGet]
74	        public IActionResult List()
75	        {
76	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
77	            if (string.IsNullOrEmpty(userId))
78	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
79	
80	            var records = _chataiModule.GetExplorationListForAccount(userId);
81	            return Ok(records.Select(ToResponse));
82	        }
83	
84	        [HttpGet("{id}")]
85	        public IActionResult GetById(Guid id)
86	        {
87	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
88	            if (string.IsNullOrEmpty(userId))
89	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
90	
91	            var record = _chataiModule.GetExplorationById(id);
92	            if (!IsOwnedBy(record, userId))
93	                return NotFound();
94	
95	            return Ok(ToResponse(record!));
96	        }
97	
98	        /// <summary>
99	        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位，不動 history_json
100	        /// （history 只能透過 RunController.RunAdvisingExploreFlow 變動）。
101	        /// </summary>
102	        [HttpPatch("{id}")]
103	        public IActionResult UpdateDerived(Guid id, [FromBody] UpdateExplorationDerivedRequest request)
104	        {
105	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
106	            if (string.IsNullOrEmpty(userId))
107	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
108	
109	            var record = _chataiModule.GetExplorationById(id);
110	            if (!IsOwnedBy(record, userId))
111	                return NotFound();
112	
113	            var ok = _chataiModule.UpdateExplorationDerived(
114	                id,
115	                userId,
116	                request.Answers?.GetRawText(),
117	                request.Summary?.GetRawText(),
118	                request.Card?.GetRawText(),
119	                request.Fast?.GetRawText(),
120	                string.IsNullOrWhiteSpace(request.Status) ? record!.status : request.Status,
121	                DateTime.Now);
122	
123	            if (!ok)
124	                return BadRequest("更新探索紀錄失敗。");
125	
126	            return Ok();
127	        }
128	
129	        [HttpDelete("{id}")]
130	        public IActionResult Delete(Guid id)
131	        {
132	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
133	            if (string.IsNullOrEmpty(userId))
134	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
135	
136	            var record = _chataiModule.GetExplorationById(id);
137	            if (!IsOwnedBy(record, userId))
138	                return NotFound();
139	
140	            if (!_chataiModule.DeleteExploration(id, userId, DateTime.Now))
141	                return BadRequest("刪除探索紀錄失敗。");
142	
143	            return Ok();
144	        }
145	
146	        private static bool IsOwnedBy(Exploration? record, string accountName) =>
147	            record != null && !record.is_del && record.account_name == accountName;
148	
149	        private static ExplorationResponse ToResponse(Exploration record) => new()
150	        {
151	            Id = record.id,
152	            Topic = record.topic,
153	            TopicCustomLabel = record.topic_custom_label,
154	            Status = record.status,
155	            History = ParseJsonOrNull(record.history_json),
156	            Answers = ParseJsonOrNull(record.answers_json),
157	            Summary = ParseJsonOrNull(record.summary_json),
158	            Card = ParseJsonOrNull(record.card_json),
159	            Fast = ParseJsonOrNull(record.fast_json),
160	            CreatedAt = record.create_date,
161	            UpdatedAt = record.update_date,
162	        };
163	
164	        private static JsonElement? ParseJsonOrNull(string? json)
165	        {
166	            if (string.IsNullOrWhiteSpace(json)) return null;
167	            return JsonSerializer.Deserialize<JsonElement>(json);
168	        }
169	    }
170	}
