20	    {
21	        private readonly IChataiModule _chataiModule;
22	
23	        public ExplorationController(IChataiModule chataiModule)
24	        {
25	            _chataiModule = chataiModule;
26	        }
27	
28	        [HttpPost]
29	        public IActionResult SearchAccounts([FromBody] SearchAccountRequest request)
30	        {
31	            var model = new SearchAccountResponse();
32	
33	            var result = _chataiModule.GetExplorationAccountSummaryList(request.page_size, request.page, request.account_name);
34	
35	            model.Items = result.data;
36	            model.TotalCount = result.totalCount;
37	
38	            return Ok(model);
39	        }
40	
41	        [HttpPost]
42	        public IActionResult Search([FromBody] SearchRequest request)
43	        {
44	            var model = new SearchResponse();
45	
46	            var result = _chataiModule.GetExplorationListByAccount(request.page_size, request.page, request.account_name, request.status);
47	
48	            var items = AutoMapperHelper.MapList<Exploration, SearchResponse.ExplorationResponse>(result.data.ToList());
49	
50	            items.ForEach(x =>
51	            {
52	                x.duration_seconds = x.status == "completed"
53	                    ? (x.update_date - x.create_date).TotalSeconds
54	                    : null;
55	            });
56	
57	            model.Items = items;
58	            model.TotalCount = result.totalCount;
59	
60	            return Ok(model);
61	        }
62	
63	        [HttpPost]
64	        public IActionResult Delete([FromBody] DeleteRequest request)
65	        {
66	            var result = _chataiModule.DeleteExploration(request.id, request.account_name, DateTime.Now);
67	
68	            if (!result)
69	                throw new CustomException("刪除失敗，請重新再試");
70	
71	            return Ok();
72	        }
73	    }
74	}
